impl Default for MitosisConfig {
    fn default() -> Self {
        MitosisConfig {
            enabled: Self::default_enabled(),
            first_failure_only: Self::default_first_failure_only(),
            force_failure_threshold: 0,
            repeat_interval: 0,
        }

pub force_failure_threshold: u32,

